<?php require 'admin_guard.php';require 'admin_db.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['reportID'];$status=$_POST['status']==='RESOLVED'?'RESOLVED':'REJECTED';$s=mysqli_prepare($conn,'UPDATE content_reports SET status=? WHERE reportID=?');mysqli_stmt_bind_param($s,'si',$status,$id);mysqli_stmt_execute($s);if(!empty($_POST['delete_target'])){ $type=$_POST['type'];$target=mysqli_real_escape_string($conn,$_POST['targetID']);if($type==='USER')mysqli_query($conn,"DELETE FROM user_info WHERE userID='$target'");elseif($type==='COURSE')mysqli_query($conn,"DELETE FROM course WHERE coursecode='$target'");elseif($type==='REPO')mysqli_query($conn,"DELETE FROM repository WHERE repoID='$target'");elseif($type==='GROUP')mysqli_query($conn,"DELETE FROM group_info WHERE groupID='$target'");}}
$rows=mysqli_query($conn,'SELECT * FROM content_reports ORDER BY status,created_at DESC');?>
<!doctype html><html><head><title>Manage Reports</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>Manage Reports</h1><a class="btn" href="admin_dashboard.php">Dashboard</a></div><div class="panel tablewrap"><table><tr><th>ID</th><th>Reporter</th><th>Type</th><th>Target</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=$r['reportID']?></td><td><?=$r['reporterID']?></td><td><?=$r['report_type']?></td><td><?=$r['targetID']?></td><td><?=htmlspecialchars($r['reason'])?></td><td><?=$r['status']?></td><td><form method="post"><input type="hidden" name="reportID" value="<?=$r['reportID']?>"><input type="hidden" name="type" value="<?=$r['report_type']?>"><input type="hidden" name="targetID" value="<?=$r['targetID']?>"><select name="status"><option>RESOLVED</option><option>REJECTED</option></select><label><input type="checkbox" name="delete_target"> Delete target</label><button>Apply</button></form></td></tr><?php endwhile;?></table></div></div></body></html>
